"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[9936],{928(a){a.exports=JSON.parse('{"title":"E18E\uac00 \ubb54\ub370(\uc9c4\uc9dc \ubaa8\ub984)","date":"2024-08-14","coverUrl":null,"html":"<h2 data-notion-block-id=\\"8d21a27c-c00e-4e7c-a4a9-4786e0ac9750\\" id=\\"8d21a27c-c00e-4e7c-a4a9-4786e0ac9750\\">E18E\uac00 \ubb54\ub370</h2><a href=\\"https://e18e.dev/blog/e18e.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://e18e.dev/blog/e18e.html</a><p data-notion-block-id=\\"b56cc3bc-ea37-4237-b4a5-abee5642a051\\">JS \uc0dd\ud0dc\uacc4\uc758 \uc5b4\ub290 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc740 \uc758\uc874\uc131\uc744 \uc794\ub729 \ub4e4\uace0 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc544 \uc18d\ub3c4\uac00 \ub290\ub824\uc9c8 \ub54c\ub3c4 \uc788\uace0, \ub808\uac70\uc2dc \uc9c0\uc6d0\uc744 \ub04a\uc9c0 \uc54a\uc544 \uc774\uc804 \ubc84\uc804\ub4e4\uc744 \uc704\ud55c \ucf54\ub4dc\ub4e4\uc744 \uac16\uace0 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4. \ucd5c\uadfc\uc5d0\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc774 \ub2e4\uc591\ud574\uc9c0\uba74\uc11c, \ub300\uccb4\ub418\uba74\uc11c \uc0ac\uc774\uc988\uac00 \uc791\uac70\ub098 \uc758\uc874\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc5c6\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub3c4 \ub9ce\uc544\uc84c\uc2b5\ub2c8\ub2e4. E18E \ud300\uc740 \ud328\ud0a4\uc9c0 \ucd95\uc18c\ub97c \uc704\ud55c \uac00\uc774\ub4dc\ub098 ESLint \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc81c\uacf5\ud574\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"30089452-ccef-4425-905c-3aa8f87fbb81\\" id=\\"30089452-ccef-4425-905c-3aa8f87fbb81\\">\uc9c0\uc800\ubd84\ud55c React \uc0c1\ud0dc \ub9ac\ud329\ud1a0\ub9c1\ud558\uae30</h2><a href=\\"https://alexkondov.com/refactoring-a-messy-react-component/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://alexkondov.com/refactoring-a-messy-react-component/</a><p data-notion-block-id=\\"418d5124-381d-4688-a8a5-65a878810ef9\\"><b>\uc2ec\uc724\uc12d</b>: React 16.8 \ub2f9\uc2dc hook\uc744 \ucc98\uc74c \uc811\ud560 \ub2f9\uc2dc\uc758 \ucf54\ub4dc\ub97c \ubcf4\uba74 \uc218\ub9ce\uc740 \uc0c1\ud0dc\uc640 \ud568\uaed8 \ubd84\ub9ac\ud558\uae30 \uc5b4\ub835\uac8c \ub418\uc5b4\uc788\uc2b5\ub2c8\ub2e4. \uc800\uc790\ub294 \uc5b4\ub5bb\uac8c \ub2e8\uacc4\uc801\uc73c\ub85c \ub9ac\ud329\ud1a0\ub9c1\uc744 \uc811\uadfc\ud588\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\uace0, \uc5b4\ub5bb\uac8c \uc811\uadfc\ud558\uba74 \uc88b\uc740\uc9c0 \uacfc\uc815\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4. \ubaa8\ub4e0 \uacbd\uc6b0\uc5d0 \uc774 \ubc29\uc2dd\uc774 \uc801\uc6a9\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, \uc694\uad6c\uc0ac\ud56d\uc5d0 \ub530\ub978 \ubd84\ub9ac\ud558\ub294 \uc811\uadfc \ubc29\uc2dd\uc774\ub098 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ucd94\uac00\ud558\ub294 \ubc29\uc2dd\uc740 \ub9ce\uc740 \uacbd\uc6b0\uc5d0 \uc801\uc6a9 \uac00\ub2a5\ud558\uae30 \ub54c\ubb38\uc5d0, \ub098\uc758 \ucf54\ub4dc \uc811\uadfc \ubc29\uc2dd\uacfc \ube44\uad50\ud574\uc11c \uc801\uc6a9\ud574\ubcfc\ub9cc \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"8ab7a2e3-c415-43f0-9fe6-08e4a334da92\\" id=\\"8ab7a2e3-c415-43f0-9fe6-08e4a334da92\\">Unstyled \ucef4\ud3ec\ub10c\ud2b8 \ub9cc\ub4e4\uae30</h2><a href=\\"https://buildui.com/posts/avoiding-premature-abstraction-with-unstyled-react-components\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://buildui.com/posts/avoiding-premature-abstraction-with-unstyled-react-components</a><p data-notion-block-id=\\"8df25444-5895-4d39-9afa-879ea8aeb1cb\\"><b>\uc2ec\uc724\uc12d</b>: \uc7ac\uc0ac\uc6a9 \uac00\ub2a5\ud55c \ucef4\ud3ec\ub10c\ud2b8\ub97c \ub9cc\ub4e4 \uacbd\uc6b0 \uac00\uc7a5 \ub9ce\uc774 \uace0\ub824\ub418\ub294 \ubd80\ubd84\uc740 \\"\uc5b4\ub5a4 \ubd80\ubd84\uc744 \uc7ac\uc0ac\uc6a9 \uac00\ub2a5\ud558\uac8c \ub9cc\ub4e4\uae4c\\"\uc774\uace0, \uadf8 \uc911\uc5d0 \uac00\uc7a5 \ubb38\uc81c\uac00 \ub418\ub294 \ubd80\ubd84\uc740 \uc2a4\ud0c0\uc77c\ub9c1\uacfc \ub3d9\uc791\uc785\ub2c8\ub2e4. \ubc84\ud2bc\uc774 \uc694\uad6c\uc0ac\ud56d\uc774 \ubcc4\ub85c \uc5c6\uace0, \uc2a4\ud0c0\uc77c\uc774 \ub4e4\ucb49\ub0a0\ucb49\uc77c \uacbd\uc6b0\uc758 \ucef4\ud3ec\ub10c\ud2b8 \uc81c\uc791\uc744 \ub530\ub77c\uac04 \uae00\uc774\uc9c0\ub9cc, \ucef4\ud3ec\ub10c\ud2b8\ub85c \ubd84\ub9ac\ud588\uc744 \ub54c \uac00\uc7a5 \uc704\ud5d8\ud55c \ubd80\ubd84 \uc911 \ud558\ub098\uac00 \uc2a4\ud0c0\uc77c\ub9c1\uc774\uae30 \ub54c\ubb38\uc5d0 \ud55c \ubc88 \uc0dd\uac01\ud560\ub9cc\ud55c \ud3ec\uc778\ud2b8\ub97c \uc900\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"6cdc5394-ffa7-4f23-b798-8d9d5bd83e51\\" id=\\"6cdc5394-ffa7-4f23-b798-8d9d5bd83e51\\">\ud504\ub860\ud2b8\uc5d4\ub4dc\uc758 \ubcf4\uc548</h2><a href=\\"https://www.trevorlasn.com/blog/frontend-security-checklist\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.trevorlasn.com/blog/frontend-security-checklist</a><p data-notion-block-id=\\"6c4b72c6-a2c7-4222-bd4f-5ddeec685e01\\"><b>\uc2ec\uc724\uc12d</b>: \uac04\ub2e8\ud558\uac8c \ubcf4\ub294 \ud504\ub860\ud2b8\uc5d4\ub4dc\uc5d0\uc11c \uc9c0\ucf1c\uc57c \ud560 \ubcf4\uc548\ub4e4\uc785\ub2c8\ub2e4. \uae30\ubcf8\uc778 XSS, XSRF, \ud658\uacbd \ubcc0\uc218 \ub178\ucd9c, CSP\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubcf4\uc548\uc740 \ubc31\uc5d4\ub4dc\uc5d0 \uad00\ub828\ub41c \ubd80\ubd84\uc774 \ub9ce\uae30\ub3c4 \ud558\uace0, \ud504\ub860\ud2b8\uc5d4\ub4dc\uc5d0\uc11c DB\ub85c \ubc14\ub85c \uc811\uadfc\ud558\ub294 \uacbd\uc6b0\ub3c4 \ub9ce\uae30 \ub54c\ubb38\uc5d0, <a href=\\"https://cheatsheetseries.owasp.org/IndexTopTen.html\\">OWSAP Top 10</a>\uc744 \ud1b5\ud574 \ub2e4\ub978 \ubd80\ubd84\ub3c4 \uc0b4\ud3b4\ubcf4\ub294 \uac8c \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"9e3ac724-258e-480b-b86a-ff40f2180ebb\\" id=\\"9e3ac724-258e-480b-b86a-ff40f2180ebb\\">\uc774\uc81c CSS5\ub77c\uace0 \ubd88\ub7ec\uc904\ub798\uc694?</h2><a href=\\"https://www.smashingmagazine.com/2024/08/time-to-talk-about-css5/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2024/08/time-to-talk-about-css5/</a><p data-notion-block-id=\\"87e0bd35-e68b-4a2f-a6c5-eb0c121d0b5c\\">CSS3\uc73c\ub85c \uc815\uc758\ub41c \uc774\ud6c4 \uc0dd\ud0dc\uacc4\uc5d0 \ucd5c\uc2e0 CSS\ub97c \uc801\uc6a9\ud558\ub824\ub294 \uc6c0\uc9c1\uc784\uc774 \ub9ce\uc544\uc84c\uc9c0\ub9cc, \uc774\ud6c4 \ub124\uc774\ubc0d\uc774 \uc5c6\uc774 Modern CSS\ub77c\uace0 \uc9c0\uce6d\ub418\uae30\ub9cc \ud558\uace0 \ubc84\uc800\ub2dd\uc744 \ub530\ub85c \ud558\uc9c4 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \uac04\ub2e8\ud55c CSS \uc5ed\uc0ac\uc640 \ubc84\uc800\ub2dd\uc744 \ud574\uc57c \ud55c\ub2e4\ub294 \uc774\uc720\uc5d0 \ub300\ud574 \uc124\uba85\ud558\ub294 \uac00\ubcbc\uc6b4 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"acdd24ff-f568-4b9c-9ae1-6b9cdbcb9598\\" id=\\"acdd24ff-f568-4b9c-9ae1-6b9cdbcb9598\\">\ud22c\uba85\ub3c4\uac00 \uc788\ub294 \ub3d9\uc601\uc0c1 \ucd5c\uc801\ud654\ud558\uae30</h2><a href=\\"https://jakearchibald.com/2024/video-with-transparency/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jakearchibald.com/2024/video-with-transparency/</a><p data-notion-block-id=\\"3c800fd4-203a-4256-86d2-c43e3371aaa9\\">AVIF\uc640 VP9 + HEVC\ub97c \uc0ac\uc6a9\ud574\ubcf4\uba74\uc11c \ud22c\uba85\ub3c4 \uc788\ub294 \uc601\uc0c1\uc744 \uc6f9\uc5d0\uc11c \ubcf4\uc774\uae30 \uc704\ud55c \uacfc\uc815\uc744 \uc54c\ub824\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ud604\uc7ac\ub9cc \uc788\ub294 \ubc84\uadf8\uc77c \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uac00\ubccd\uac8c \uc774\ub7f0 \uc774\uc288\ub4e4\uc774 \uc788\ub2e4\ub77c\ub294 \uac83\uc744 \uc54c\uc544\ub450\uba74 \uc88b\uc744 \uac83 \uac19\ub124\uc694.</p><h2 data-notion-block-id=\\"38362166-9494-45ac-b7d7-067811f98b97\\" id=\\"38362166-9494-45ac-b7d7-067811f98b97\\"><code>cqi</code>\uc744 \uc0ac\uc6a9\ud558\uba74\uc11c \uacaa\uc744 \uc218 \uc788\ub294 \ubb38\uc81c</h2><a href=\\"https://frontendmasters.com/blog/what-if-you-used-container-units-for-everything/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/what-if-you-used-container-units-for-everything/</a><p data-notion-block-id=\\"804086c7-5394-4c35-901c-9d6121ba07a4\\">\ucee8\ud14c\uc774\ub108 \ub2e8\uc704\ub97c \ubaa8\ub4e0 \uacf3\uc5d0 \uc0ac\uc6a9\ud558\uba74 \uc7a0\uc7ac\uc801\uc778 \ubb38\uc81c\uac00 \ub098\uc62c \uc218 \uc788\uace0, \ubcf5\uc7a1\ud55c \ub808\uc774\uc544\uc6c3\uc774 \uc544\ub2cc \uacbd\uc6b0, \uad73\uc774 \ud544\uc694\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac00\ubcbc\uc6b4 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"58569723-f22d-4cfc-a571-1bb8a003648a\\" id=\\"58569723-f22d-4cfc-a571-1bb8a003648a\\">React \ucef4\ud30c\uc77c\ub7ec\uc758 \uae4a\uc740 \uc774\ud574</h2><a href=\\"https://yongseok.me/blog/react_compiler_1/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://yongseok.me/blog/react_compiler_1/</a><p data-notion-block-id=\\"963fa0c7-d315-4d27-8605-c04f710f0b85\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/bab36975-b9d2-474a-b5a9-babe0f64cb01#156b3589-12b0-4b07-bcf4-0c72c859e299\\">React \ucef4\ud30c\uc77c\ub7ec\uc5d0 \ub300\ud55c \uc774\ud574</a>\uc640 \uac19\uc740 \uc26c\uc6b4 \uae00\uc774\ub098 <a href=\\"https://ones-to-watch.ethansup.net/news/post/022fc2c2-88d3-4c20-9075-defdea8ae65c#7c39d4b0-fc93-4fbd-9b02-b095dbf45c63\\">React \ucef4\ud30c\uc77c\ub7ec \uac1c\ubc1c\uc790\uc758 \uae00</a>\uac19\uc740 \uac04\ub2e8\ud558\uac8c \uc18c\uac1c\ud558\ub294 \uae00\ub85c \uc785\ubb38\ud558\uace0, \ucef4\ud30c\uc77c\ub7ec \uc774\ub860\uc774\ub098 \ucf54\ub4dc\uc5d0 \ub354 \uc9d1\uc911\ud558\uace0 \uc2f6\uc740 \uac1c\ubc1c\uc790\ub97c \uc704\ud55c \ub525\ub2e4\uc774\ube0c \uae00\uc785\ub2c8\ub2e4. \ucef4\ud30c\uc77c\ub7ec \uac1c\ubc1c\uc790\uc758 \uae00\uc5d0\uc11c\ub294 IR\uacfc SSA\ub77c\ub294 \uac1c\ub150\uc744 \uac04\ub2e8\ud558\uac8c \ub118\uc5b4\uac14\uc9c0\ub9cc, \uc774 \uae00\uc740 \ub9e4\uc6b0 \uc790\uc138\ud558\uac8c \ub2e4\ub8e8\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1e438941-d71a-4385-a9ed-511aa590f066\\" id=\\"1e438941-d71a-4385-a9ed-511aa590f066\\">Xstate \uc18c\uac1c \uae00</h2><a href=\\"https://tkdodo.eu/blog/introducing-x-state-store\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/introducing-x-state-store</a><p data-notion-block-id=\\"8ead8b6b-fb8a-4843-a12e-4a8807e304cd\\">FSM \uc774\ub860\uc744 \uc27d\uac8c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d, \uadf8\ub9ac\uace0 UI \ud504\ub808\uc784\uc6cc\ud06c\ub4e4\uc5d0 \uc798 \uc801\uc6a9\ub420 \uc218 \uc788\ub3c4\ub85d \ub9cc\ub4e0 Xstate\uc5d0 \ub300\ud55c \uc18c\uac1c\uae00\uc785\ub2c8\ub2e4. \ubcf5\uc7a1\ud55c \uc0c1\ud0dc\ub97c \uad6c\ud604\ud560 \ub54c \ube5b\uc744 \ubc14\ub77c\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc774\ubbc0\ub85c, \uac1c\ub150\ub9cc \uc54c\uace0 \uacc4\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"aa840b2b-5df0-450e-971e-474bee046564\\" id=\\"aa840b2b-5df0-450e-971e-474bee046564\\">\ub808\ud2b8\ub85c \ud6a8\uacfc \uad6c\ud604\ud558\uae30</h2><a href=\\"https://blog.maximeheckel.com/posts/the-art-of-dithering-and-retro-shading-web/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.maximeheckel.com/posts/the-art-of-dithering-and-retro-shading-web/</a><p data-notion-block-id=\\"2c80d009-f311-4116-91dc-105e32445708\\">WebGL\uacfc React Three Fiber\ub97c \uae30\ubc18\uc73c\ub85c \ub808\ud2b8\ub85c \ud6a8\uacfc\ub97c \uad6c\ud604\ud558\uae30 \uc704\ud574 \ub80c\ub354\ub9c1 \uae30\uc220(\ub514\ub354\ub9c1, \uc591\uc790\ud654, \ud53d\uc140\ud654)\ub97c \ubc30\uc6b8 \uc218 \uc788\ub294 \uae00\uc785\ub2c8\ub2e4.</p>"}')}}]);